const dir=load("write_check_dir");
let prose=load("write_prose");
prose=prose.replace("Fenwick Instrument Repairs services brass and woodwind instruments. In January 2026, the team began trialling a shared bench schedule: jobs awaiting parts and jobs ready for work had previously appeared on separate paper sheets. The team chose Benchline after checking that it could distinguish those statuses.", "In January 2026, the team at Fenwick Instrument Repairs began a six-week trial of a shared bench schedule. The workshop services brass and woodwind instruments; jobs awaiting parts and jobs ready for work had previously appeared on separate paper sheets. The team chose Benchline after checking that it could distinguish those statuses.");
prose=prose.replace("## The workshop sets the terms", "## Benchline provides setup and training");
store("write_prose", prose);
text(await tools.apply_patch("*** Begin Patch\n*** Update File: "+dir+"/draft.md\n@@\n-Fenwick Instrument Repairs services brass and woodwind instruments. In January 2026, the team began trialling a shared bench schedule: jobs awaiting parts and jobs ready for work had previously appeared on separate paper sheets. The team chose Benchline after checking that it could distinguish those statuses.\n+In January 2026, the team at Fenwick Instrument Repairs began a six-week trial of a shared bench schedule. The workshop services brass and woodwind instruments; jobs awaiting parts and jobs ready for work had previously appeared on separate paper sheets. The team chose Benchline after checking that it could distinguish those statuses.\n@@\n-## The workshop sets the terms\n+## Benchline provides setup and training\n*** End Patch"));
const created=await tools.exec_command({cmd:"mktemp -d /private/var/folders/cs/vgp_x_353zd9frkjpysp7zdw0000gn/T/kntnt-native-session-7mb8qw2d/scratch/write-uv.XXXXXX","max_output_tokens":1000});
const tmp=created.output.trim();
try {
 const measured=await tools.exec_command({cmd:`TMPDIR='${tmp}' UV_NO_CACHE=1 UV_NO_PROJECT=1 uv run --no-cache --no-project "$PWD/.agents/skills/kntnt/library/scripts/article_anatomy.py" - < '${dir}/draft.md'`,"max_output_tokens":9000});
 store("write_anatomy", measured);
 text(measured);
 text(await tools.apply_patch("*** Begin Patch\n*** Add File: "+dir+"/anatomy.json\n"+measured.output.trimEnd().split("\n").map(l=>"+"+l).join("\n")+"\n*** End Patch"));
} finally {
 text(await tools.exec_command({cmd:`python3 -c 'import pathlib, shutil, sys; p=pathlib.Path(sys.argv[1]); assert p.parent == pathlib.Path("/private/var/folders/cs/vgp_x_353zd9frkjpysp7zdw0000gn/T/kntnt-native-session-7mb8qw2d/scratch") and p.name.startswith("write-uv."); shutil.rmtree(p)' '${tmp}'`,"max_output_tokens":1000}));
}

